        12 => x"000A2503",
        13 => x"00AA2423",
        14 => x"008A2583",
        15 => x"000A2603",
        16 => x"00160463",
        17 => x"00100E93",
        18 => x"00100693",
        19 => x"0000006F"
    );
    constant HEX_FILE : string := write_hex("/tmp/tb_hazard_load_use.hex", PROG);

begin
    clk <= not clk after CLK_PERIOD / 2;

    dut: entity work.pipeline_top
        generic map (MEM_DEPTH => 256, IMEM_INIT => HEX_FILE)
